-- Generated by scripts/build_compiled.py from src/fraudrules/rules/synthetic-identity/si-003-address-shared-across-ssns.yaml. Do not edit.
-- SI-003 Mailing address shared by many SSNs within six months
SELECT 'SI-003' AS rule_id, 'applications' AS anchor_table, a.id AS anchor_id
FROM applications AS a
JOIN applications AS b ON b.address_token = a.address_token AND b.ts <= a.ts AND b.ts > a.ts - 15552000
WHERE 1 = 1 AND 1 = 1
GROUP BY a.id
HAVING COUNT(DISTINCT b.ssn_token) >= 4;
